import { BREAD_BUTTER_20260917_CASES as authoredCases, SYNTHETIC_CLINICAL_RELEASE } from "@gamify-surgery/clinical-content";
import { describe, expect, it } from "vitest";
import {
  createInitialGameState,
  deserializeGameState,
  gameReducer,
  getCurrentQuestion,
  getEligibleServiceRoute,
  serializeGameState,
  type GameState,
} from "../src";

// These tests admit fresh cases. New scored versions must be checked against
// their current concept, while the original export remains for frozen saves.
const BREAD_BUTTER_20260917_CASES = authoredCases.map(c => {
  const current = SYNTHETIC_CLINICAL_RELEASE.cases.find(current => current.id === c.id)!;
  if (current.earliestFacilityStage !== c.earliestFacilityStage) throw new Error(`Changed facility stage: ${c.id}`);
  return { ...current, earliestFacilityStage: c.earliestFacilityStage };
});
type BreadButterCase = (typeof BREAD_BUTTER_20260917_CASES)[number];

function prepared(seed: string, level: 0 | 1 | 2): GameState {
  const state = createInitialGameState(undefined, {
    campaignId: `campaign.bread-butter-sept17.${seed}`,
    campaignSeed: seed,
    createdAtRealMs: 0,
  });
  state.facilityLevel = level;
  state.encounters = {};
  state.openChartEncounterId = null;
  state.attendedEncounterId = null;
  state.nextRoutineArrivalTick = Number.MAX_SAFE_INTEGER;
  state.rooms.push(
    { id: "room.bread-butter-sept17.examination", roomDefinitionId: "room.examination", x: 33, y: 26, orientation: 0, doorSide: null, upgradeLevel: 1, cleanliness: 100 },
    { id: "room.bread-butter-sept17.minor-procedure", roomDefinitionId: "room.minor_procedure", x: 33, y: 23, orientation: 0, doorSide: null, upgradeLevel: 1, cleanliness: 100 },
    ...([24, 25, 26, 27, 28] as const).map((y) => ({ id: `room.bread-butter-sept17.hall.${y}`, roomDefinitionId: "room.hallway", x: 32, y, orientation: 0 as const, doorSide: null, upgradeLevel: 1 as const, cleanliness: 100 })),
  );
  state.doors.push(
    { id: "door.bread-butter-sept17.examination", roomId: "room.bread-butter-sept17.examination", side: "west", offset: 1, exterior: false },
    { id: "door.bread-butter-sept17.minor-procedure", roomId: "room.bread-butter-sept17.minor-procedure", side: "west", offset: 1, exterior: false },
    { id: "door.bread-butter-sept17.front", roomId: "room.instance.founder_desk", side: "west", offset: 0, exterior: false },
  );
  return state;
}

function stateWithoutExaminationCapability(seed: string): GameState {
  const state = createInitialGameState(undefined, {
    campaignId: `campaign.bread-butter-sept17.${seed}`,
    campaignSeed: seed,
    createdAtRealMs: 0,
  });
  state.rooms = state.rooms.filter(
    (room) => room.roomDefinitionId !== "room.examination",
  );
  state.doors = state.doors.filter((door) =>
    state.rooms.some((room) => room.id === door.roomId),
  );
  return state;
}

function admit(
  state: GameState,
  clinicalCase: BreadButterCase,
  encounterId: string,
  operationId: string,
): GameState {
  return gameReducer(state, {
    type: "ADMIT_PATIENT",
    operationId,
    encounterId,
    caseId: clinicalCase.id,
    patientDisplayName: `Bread Butter Patient ${encounterId}`,
    arrivalClass: "routine",
  });
}

function ready(
  state: GameState,
  encounterId: string,
  operationPrefix: string,
): GameState {
  let next = state;
  for (let attempt = 0; attempt < 1_500; attempt += 1) {
    if (getCurrentQuestion(next, encounterId)) {
      return next;
    }
    const encounter = next.encounters[encounterId];
    if (!encounter) {
      throw new Error(`${encounterId} disappeared before becoming ready`);
    }
    next =
      encounter.lifecycle === "waiting_unopened" &&
      encounter.patientMovement === null
        ? gameReducer(next, {
            type: "OPEN_CHART",
            operationId: `${operationPrefix}.open.${attempt}`,
            encounterId,
          })
        : gameReducer(next, {
            type: "ADVANCE_TICK",
            operationId: `${operationPrefix}.tick.${attempt}`,
          });
  }
  throw new Error(`${encounterId} did not become ready`);
}

function stationaryAtCare(
  state: GameState,
  encounterId: string,
  operationPrefix: string,
): GameState {
  let next = state;
  for (let attempt = 0; attempt < 1_500; attempt += 1) {
    const encounter = next.encounters[encounterId];
    if (
      getCurrentQuestion(next, encounterId) &&
      encounter?.patientMovement === null &&
      encounter.assignedRoomInstanceId !== null
    ) {
      return next;
    }
    next = gameReducer(next, {
      type: "ADVANCE_TICK",
      operationId: `${operationPrefix}.tick.${attempt}`,
    });
  }
  throw new Error(`${encounterId} did not become stationary at care`);
}

function submit(
  state: GameState,
  encounterId: string,
  correct: boolean,
  operationId: string,
  reviewedAtMs: number,
): GameState {
  const question = getCurrentQuestion(state, encounterId);
  if (!question) {
    throw new Error(`${encounterId} has no current question`);
  }
  const choice = question.node.answerChoices.find(
    (candidate) => candidate.isCorrect === correct,
  );
  if (!choice) {
    throw new Error(
      `${question.node.id} has no ${correct ? "correct" : "incorrect"} choice`,
    );
  }
  return gameReducer(state, {
    type: "SUBMIT_ANSWER",
    operationId,
    encounterId,
    decisionNodeId: question.node.id,
    answerChoiceId: choice.id,
    reviewedAtMs,
  });
}

function acknowledge(
  state: GameState,
  encounterId: string,
  operationId: string,
): GameState {
  const encounter = state.encounters[encounterId];
  const step = encounter?.steps[encounter.currentNodeIndex];
  if (!step) {
    throw new Error(`${encounterId} has no feedback to acknowledge`);
  }
  return gameReducer(state, {
    type: "ACKNOWLEDGE_DECISION_FEEDBACK",
    operationId,
    encounterId,
    decisionNodeId: step.decisionNodeId,
  });
}

function advanceUntilResult(
  state: GameState,
  encounterId: string,
  operationPrefix: string,
): GameState {
  let next = state;
  const pending = next.encounters[encounterId]?.pendingResult;
  if (!pending) {
    throw new Error(`${encounterId} did not schedule a result`);
  }
  let elapsed = 0;
  while (
    next.encounters[encounterId]?.pendingResult?.deliveredAtTick === null &&
    elapsed < 1_000
  ) {
    expect(getCurrentQuestion(next, encounterId)).toBeNull();
    expect(next.encounters[encounterId]?.deliveredResultNarratives).toEqual([]);
    next = gameReducer(next, {
      type: "ADVANCE_TICK",
      operationId: `${operationPrefix}.${next.facilityTick}`,
    });
    elapsed += 1;
  }
  expect(next.encounters[encounterId]?.pendingResult?.deliveredAtTick).not.toBeNull();
  return next;
}

const singleCases = BREAD_BUTTER_20260917_CASES.filter(
  (clinicalCase) => clinicalCase.decisionNodes.length === 1,
);
const gatedCases = BREAD_BUTTER_20260917_CASES.filter(
  (clinicalCase) =>
    clinicalCase.decisionNodes.length === 2 &&
    clinicalCase.decisionNodes[0]?.resultGateAfter !== null,
);
const nongatedCases = BREAD_BUTTER_20260917_CASES.filter(
  (clinicalCase) =>
    clinicalCase.decisionNodes.length === 2 &&
    clinicalCase.decisionNodes[0]?.resultGateAfter === null,
);

describe("September 17 bread-and-butter production flows", () => {
  it("contains the authored case, node, and pathway mix", () => {
    expect(BREAD_BUTTER_20260917_CASES).toHaveLength(52);
    expect(
      BREAD_BUTTER_20260917_CASES.flatMap(
        (clinicalCase) => clinicalCase.decisionNodes,
      ),
    ).toHaveLength(80);
    expect(singleCases).toHaveLength(24);
    expect(gatedCases).toHaveLength(16);
    expect(nongatedCases).toHaveLength(12);
  });

  it.each(
    BREAD_BUTTER_20260917_CASES.map(
      (clinicalCase, index) => [index, clinicalCase] as const,
    ),
  )(
    "runs case %s through every authored node with one FSRS review per node",
    (index, clinicalCase) => {
      const encounterId = `encounter.bread-butter-sept17.${index}`;
      const prefix = `bread-butter-sept17.${index}`;
      let state = prepared(`all-${index}`, clinicalCase.earliestFacilityStage);
      state = admit(
        state,
        clinicalCase,
        encounterId,
        `${prefix}.admit`,
      );
      expect(state.operationReceipts[`${prefix}.admit`]?.status).toBe("applied");

      for (
        let nodeIndex = 0;
        nodeIndex < clinicalCase.decisionNodes.length;
        nodeIndex += 1
      ) {
        state = ready(state, encounterId, `${prefix}.node-${nodeIndex}.ready`);
        const question = getCurrentQuestion(state, encounterId);
        const authoredNode = clinicalCase.decisionNodes[nodeIndex];
        expect(question?.node.id).toBe(authoredNode?.id);
        if (!question || !authoredNode) {
          throw new Error(`${clinicalCase.id} is missing node ${nodeIndex}`);
        }

        state = submit(
          state,
          encounterId,
          true,
          `${prefix}.node-${nodeIndex}.answer`,
          index * 100 + nodeIndex + 1,
        );
        expect(
          state.learningHistories[question.node.primaryConceptId]?.reviews,
        ).toHaveLength(1);

        const isFinal = nodeIndex === clinicalCase.decisionNodes.length - 1;
        if (isFinal) {
          expect(state.encounters[encounterId]).toMatchObject({
            lifecycle: "resolved_summary_available",
            resolutionReason: "completed",
          });
          continue;
        }

        const gate = authoredNode.resultGateAfter;
        if (gate) {
          expect(state.encounters[encounterId]?.pendingResult).toMatchObject({
            resultTypeId: gate.resultTypeId,
            deliveredAtTick: null,
          });
          expect(getCurrentQuestion(state, encounterId)).toBeNull();
          state = acknowledge(
            state,
            encounterId,
            `${prefix}.node-${nodeIndex}.acknowledge`,
          );
          state = advanceUntilResult(
            state,
            encounterId,
            `${prefix}.node-${nodeIndex}.wait`,
          );
          expect(
            state.encounters[encounterId]?.deliveredResultNarratives,
          ).toContain(gate.resultNarrative);
        } else {
          expect(state.encounters[encounterId]?.pendingResult).toBeNull();
          state = acknowledge(
            state,
            encounterId,
            `${prefix}.node-${nodeIndex}.acknowledge`,
          );
          expect(state.encounters[encounterId]?.pendingResult).toBeNull();
          expect(
            state.encounters[encounterId]?.deliveredResultNarratives,
          ).toEqual([]);
        }
      }

      for (const node of clinicalCase.decisionNodes) {
        expect(
          state.learningHistories[node.primaryConceptId]?.reviews,
        ).toHaveLength(1);
        if (node.primaryConceptId === "concept.perianal-abscess.source-control-and-antibiotic-selection.v1") {
          expect(state.learningHistories["concept.perianal-abscess.prompt-drainage"]?.reviews).toHaveLength(0);
        }
      }
    },
  );

  it.each(
    nongatedCases.map((clinicalCase, index) => [index, clinicalCase] as const),
  )(
    "keeps nongated two-step case %s synchronous after a corrected-forward answer",
    (index, clinicalCase) => {
      const encounterId = `encounter.bread-butter-sept17.nongated.${index}`;
      const prefix = `bread-butter-sept17.nongated.${index}`;
      let state = admit(
        prepared(`nongated-${index}`, clinicalCase.earliestFacilityStage),
        clinicalCase,
        encounterId,
        `${prefix}.admit`,
      );
      state = ready(state, encounterId, `${prefix}.first.ready`);
      const first = getCurrentQuestion(state, encounterId);
      if (!first) {
        throw new Error(`${clinicalCase.id} did not expose its first question`);
      }
      state = submit(
        state,
        encounterId,
        false,
        `${prefix}.first.wrong`,
        index + 1,
      );
      expect(state.encounters[encounterId]?.steps[0]?.answer).toMatchObject({
        correct: false,
        correctedForward: true,
        ratingIntent: "Again",
      });
      expect(state.encounters[encounterId]?.pendingResult).toBeNull();

      state = acknowledge(state, encounterId, `${prefix}.first.acknowledge`);
      expect(state.encounters[encounterId]?.pendingResult).toBeNull();
      expect(state.encounters[encounterId]?.deliveredResultNarratives).toEqual(
        [],
      );
      state = ready(state, encounterId, `${prefix}.second.ready`);
      expect(getCurrentQuestion(state, encounterId)?.node.id).toBe(
        clinicalCase.decisionNodes[1]?.id,
      );
      state = submit(
        state,
        encounterId,
        true,
        `${prefix}.second.correct`,
        index + 10_000,
      );
      expect(state.encounters[encounterId]).toMatchObject({
        lifecycle: "resolved_summary_available",
        resolutionReason: "completed",
        pendingResult: null,
      });
      expect(
        state.learningHistories[first.node.primaryConceptId]?.reviews,
      ).toHaveLength(1);
    },
  );

  it("rejects a case before its authored facility stage", () => {
    const clinicalCase = BREAD_BUTTER_20260917_CASES.find(
      (candidate) => candidate.earliestFacilityStage === 2,
    );
    if (!clinicalCase) {
      throw new Error("Expected at least one Level 2 bread-and-butter case");
    }
    const operationId = "bread-butter-sept17.stage.reject";
    const encounterId = "encounter.bread-butter-sept17.stage";
    const state = admit(
      prepared("stage-rejection", 1),
      clinicalCase,
      encounterId,
      operationId,
    );
    expect(state.operationReceipts[operationId]).toMatchObject({
      status: "rejected",
    });
    expect(state.encounters[encounterId]).toBeUndefined();
  });

  it("preserves a corrected-forward gated encounter and idempotency across reload", () => {
    const clinicalCase = gatedCases[0];
    if (!clinicalCase) {
      throw new Error("Expected at least one gated bread-and-butter case");
    }
    const encounterId = "encounter.bread-butter-sept17.persist";
    let state = admit(
      prepared("corrected-forward-persistence", clinicalCase.earliestFacilityStage),
      clinicalCase,
      encounterId,
      "bread-butter-sept17.persist.admit",
    );
    state = ready(state, encounterId, "bread-butter-sept17.persist.first");

    const first = getCurrentQuestion(state, encounterId);
    if (!first) {
      throw new Error("Expected the first persisted question");
    }
    const patientName = state.encounters[encounterId]?.patientDisplayName;
    const choiceOrder = first.node.answerChoices.map((choice) => choice.id);
    const wrongOperationId = "bread-butter-sept17.persist.wrong-answer";
    const wrongChoice = first.node.answerChoices.find(
      (choice) => !choice.isCorrect,
    );
    if (!wrongChoice) {
      throw new Error("Expected an incorrect first-node choice");
    }
    const wrongCommand = {
      type: "SUBMIT_ANSWER" as const,
      operationId: wrongOperationId,
      encounterId,
      decisionNodeId: first.node.id,
      answerChoiceId: wrongChoice.id,
      reviewedAtMs: 99,
    };
    state = gameReducer(state, wrongCommand);
    const afterWrong = serializeGameState(state);
    state = gameReducer(state, wrongCommand);
    expect(serializeGameState(state)).toBe(afterWrong);
    expect(state.encounters[encounterId]?.steps[0]?.answer).toMatchObject({
      correct: false,
      correctedForward: true,
      ratingIntent: "Again",
    });
    expect(
      state.learningHistories[first.node.primaryConceptId]?.reviews,
    ).toHaveLength(1);
    expect(state.encounters[encounterId]?.pendingResult).not.toBeNull();

    const acknowledgementId = "bread-butter-sept17.persist.acknowledge";
    state = acknowledge(state, encounterId, acknowledgementId);
    const afterAcknowledgement = serializeGameState(state);
    state = acknowledge(state, encounterId, acknowledgementId);
    expect(serializeGameState(state)).toBe(afterAcknowledgement);
    const pending = state.encounters[encounterId]?.pendingResult;
    if (!pending) {
      throw new Error("Expected the gated answer to retain a pending result");
    }

    let restored = deserializeGameState(serializeGameState(state));
    expect(restored.encounters[encounterId]?.pendingResult).toEqual(pending);
    expect(restored.encounters[encounterId]?.pendingResult?.dueTick).toBe(
      pending.dueTick,
    );
    expect(restored.encounters[encounterId]?.patientDisplayName).toBe(
      patientName,
    );
    expect(restored.encounters[encounterId]?.frozenCase).toEqual(
      state.encounters[encounterId]?.frozenCase,
    );
    expect(
      restored.encounters[
        encounterId
      ]?.frozenCase.decisionNodes[0]?.answerChoices.map((choice) => choice.id),
    ).toEqual(choiceOrder);
    expect(
      restored.learningHistories[first.node.primaryConceptId]?.reviews,
    ).toHaveLength(1);

    restored = advanceUntilResult(
      restored,
      encounterId,
      "bread-butter-sept17.persist.wait",
    );
    restored = ready(
      restored,
      encounterId,
      "bread-butter-sept17.persist.second",
    );
    const second = getCurrentQuestion(restored, encounterId);
    if (!second) {
      throw new Error("Expected the second persisted question");
    }
    const terminalOperationId =
      "bread-butter-sept17.persist.second.wrong-answer";
    const terminalWrongChoice = second.node.answerChoices.find(
      (choice) => !choice.isCorrect,
    );
    if (!terminalWrongChoice) {
      throw new Error("Expected an incorrect terminal-node choice");
    }
    const terminalWrongCommand = {
      type: "SUBMIT_ANSWER" as const,
      operationId: terminalOperationId,
      encounterId,
      decisionNodeId: second.node.id,
      answerChoiceId: terminalWrongChoice.id,
      reviewedAtMs: 10_099,
    };
    restored = gameReducer(restored, terminalWrongCommand);
    const afterTerminal = serializeGameState(restored);
    restored = gameReducer(restored, terminalWrongCommand);
    expect(serializeGameState(restored)).toBe(afterTerminal);
    expect(restored.encounters[encounterId]).toMatchObject({
      lifecycle: "resolved_summary_available",
      resolutionReason: "completed",
    });
    expect(restored.encounters[encounterId]?.steps[1]?.answer).toMatchObject({
      correct: false,
      correctedForward: false,
      ratingIntent: "Again",
    });
    expect(
      restored.learningHistories[first.node.primaryConceptId]?.reviews,
    ).toHaveLength(1);
    expect(
      restored.learningHistories[second.node.primaryConceptId]?.reviews,
    ).toHaveLength(1);
  });

  it.each(
    BREAD_BUTTER_20260917_CASES.filter((clinicalCase) =>
      clinicalCase.id.startsWith(
        "case.bread-butter.postoperative-retention.",
      ),
    ).map((clinicalCase, index) => [index, clinicalCase] as const),
  )(
    "performs retention case %s as a five-tick bedside scan, then returns to Front Desk",
    (index, clinicalCase) => {
      const encounterId = `encounter.bread-butter-sept17.retention.${index}`;
      const prefix = `bread-butter-sept17.retention.${index}`;
      let state = admit(
        prepared(`retention-${index}`, clinicalCase.earliestFacilityStage),
        clinicalCase,
        encounterId,
        `${prefix}.admit`,
      );
      state = ready(state, encounterId, `${prefix}.ready`);
      state = stationaryAtCare(state, encounterId, `${prefix}.at-care`);
      const locationBeforeScan = state.encounters[encounterId]?.patientLocation;
      const roomBeforeScan =
        state.encounters[encounterId]?.assignedRoomInstanceId;
      state = submit(
        state,
        encounterId,
        true,
        `${prefix}.answer`,
        index + 1,
      );
      const pending = state.encounters[encounterId]?.pendingResult;
      expect(pending).toMatchObject({
        resultTypeId: "service.bladder_scan",
        routeId: "route.bladder_scan.in_house",
        deliveredAtTick: null,
        offsiteTravel: null,
        patientTravel: null,
        diagnosticTiming: { version: "diagnostic-order.v1", execution: "supported" },
      });
      const plan = pending!.diagnosticTiming!;
      expect(plan.phases.filter((phase) => phase.durationMinutes)).toEqual([
        expect.objectContaining({ kind: "acquisition", mode: "local", durationMinutes: 5,
          resource: expect.objectContaining({ patientAnchor: locationBeforeScan }) }),
      ]);
      expect(plan.phases.some((phase) => phase.kind === "interpretation")).toBe(false);
      expect(pending!.dueTick).toBe(Math.max(plan.resultReady.forecastAtTick, plan.careComplete.forecastAtTick));
      expect(pending!.dueTick - pending!.scheduledAtTick).toBeGreaterThanOrEqual(5);
      expect(pending?.resourceReservations ?? []).toEqual([]);
      expect(pending?.imagingTechnicianId ?? null).toBeNull();
      expect(pending?.providerReservation ?? null).toBeNull();

      state = acknowledge(state, encounterId, `${prefix}.acknowledge`);
      expect(state.encounters[encounterId]?.pendingResult).toMatchObject({
        offsiteTravel: null,
        patientTravel: null,
      });
      expect(state.encounters[encounterId]?.patientMovement).toBeNull();
      expect(state.encounters[encounterId]?.patientLocation).toEqual(
        locationBeforeScan,
      );
      expect(state.encounters[encounterId]?.assignedRoomInstanceId).toBe(
        roomBeforeScan,
      );
      state = deserializeGameState(serializeGameState(state));
      expect(state.encounters[encounterId]?.pendingResult).toMatchObject({
        dueTick: pending?.dueTick,
        offsiteTravel: null,
        patientTravel: null,
      });
      state = advanceUntilResult(state, encounterId, `${prefix}.wait`);
      expect(state.encounters[encounterId]?.pendingResult?.diagnosticTiming?.careComplete.reachedAtTick).toEqual(expect.any(Number));
      expect(state.encounters[encounterId]?.pendingResult?.diagnosticTiming?.phases.find((phase) => phase.kind === "acquisition")).toMatchObject({
        status: "completed", durationMinutes: 5,
      });
      expect(state.encounters[encounterId]?.patientLocation).not.toEqual(locationBeforeScan);
      expect(state.encounters[encounterId]?.assignedRoomInstanceId).not.toBe(roomBeforeScan);
      expect(state.environment.founderActivity?.targetId).not.toBe(encounterId);
      expect(
        state.encounters[encounterId]?.pendingResult?.deliveredAtTick,
      ).toBeGreaterThanOrEqual(pending!.dueTick);
    },
  );

  it("requires examination capability for the bedside bladder-scan route", () => {
    expect(
      getEligibleServiceRoute(
        stateWithoutExaminationCapability("bladder-scan-no-exam"),
        "service.bladder_scan",
        ["route.bladder_scan.in_house"],
      ),
    ).toBeNull();

    const eligible = getEligibleServiceRoute(
      prepared("bladder-scan-with-exam", 0),
      "service.bladder_scan",
      ["route.bladder_scan.in_house"],
    );
    expect(eligible?.route).toMatchObject({
      id: "route.bladder_scan.in_house",
      durationTicks: 5,
      requiredCapabilityId: "capability.examination",
      requiredCapabilityIds: [],
    });
  });
});

/// <reference types="node" />
import {writeFileSync} from "node:fs";
import {resolve} from "node:path";
import {afterAll,describe,expect,it} from "vitest";
import {GS028_20261007_LEVEL3_CASES as authoredCases,GS028_20261007_LEVEL3_TESTED_CONCEPTS as concepts,SYNTHETIC_CLINICAL_RELEASE,ANSWER_CHOICE_TIMING_REGISTRY,type SyntheticClinicalCase} from "@gamify-surgery/clinical-content";
import {PROTOTYPE_DOMAIN_CONTEXT,createInitialGameState,createPatientDisplayName,deserializeGameState,deterministicInteger,RANDOM_STREAMS,gameReducer,getAnswerChoiceServicePreview,getCurrentCapabilities,getCurrentQuestion,selectRoutineClinicalCase,serializeGameState,type ConceptReviewEvidence,type GameState} from "../src";
import {EXACT_TEST_CHOICE_ORDER_RECORDS} from "../src/test-choice-orders";
const cases = authoredCases.map(original => SYNTHETIC_CLINICAL_RELEASE.cases.find(candidate => candidate.id === original.id)! as typeof original);
const timings = ANSWER_CHOICE_TIMING_REGISTRY.filter(t => cases.some(c => c.id === t.caseId && c.decisionNodes.some(n => n.id === t.nodeId && n.questionVariantId === t.questionVariantId)));
const REAL_MS=1_800_000_000_000;
const paired=cases.filter(c=>c.decisionNodes.length===2);
const exact=EXACT_TEST_CHOICE_ORDER_RECORDS.filter(r=>cases.some(c=>c.id===r.caseId&&c.decisionNodes.some(n=>n.id===r.nodeId&&n.questionVariantId===r.questionVariantId)));
const coverage=new Map<string,Set<string>>();const frozenProfiles=new Set<string>();
const choicePreviewEvidence=new Map<string,unknown>();const eligibilityEvidence:unknown[]=[];
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v)) as T;
function prepared(seed: string, stage: 0 | 1 | 2 | 3 = 3): GameState {
  const state = createInitialGameState(undefined, { campaignId: `campaign.gs028g.${seed}`, campaignSeed: seed, createdAtRealMs: REAL_MS });
  state.facilityLevel = stage;
  state.encounters = {};
  state.openChartEncounterId = null;
  state.attendedEncounterId = null;
  state.nextRoutineArrivalTick = Number.MAX_SAFE_INTEGER;
  state.nextFinancialPostingTick = Number.MAX_SAFE_INTEGER;
  state.serviceAppointmentsEnabled = false;
  state.environment.nextLitterSpawnTick = Number.MAX_SAFE_INTEGER;
  state.environment.nextWaterCoolerDrainTick = Number.MAX_SAFE_INTEGER;
  state.rooms.push({ id: "room.gs028g.examination", roomDefinitionId: "room.examination", x: 34, y: 26, orientation: 0, doorSide: "south", upgradeLevel: 1, cleanliness: 100 });
  state.doors.push({ id: "door.gs028g.examination", roomId: "room.gs028g.examination", side: "south", offset: 1, exterior: false });
  return state;
}

function admit(state: GameState, clinicalCase: SyntheticClinicalCase, encounterId: string): GameState {
  const profiles = clinicalCase.approvedInstantiationProfiles;
  const selected = profiles?.[deterministicInteger(state.campaignSeed, RANDOM_STREAMS.clinicalPresentation, `${encounterId}|${clinicalCase.id}|approved-profile.v1`, profiles.length)];
  const name = createPatientDisplayName(state.campaignSeed, encounterId, selected?.prototypeDemographics?.sexLabel ?? clinicalCase.prototypeDemographics?.sexLabel);
  const command = { type: "ADMIT_PATIENT" as const, operationId: `${encounterId}.admit`, encounterId, caseId: clinicalCase.id, patientDisplayName: name, arrivalClass: "routine" as const };
  const next = gameReducer(state, command);
  expect(next.operationReceipts[command.operationId]?.status).toBe("applied");
  expect(gameReducer(next, command)).toBe(next);
  const frozen = next.encounters[encounterId]!.frozenCase;
  expect(frozen.selectedInstantiationProfileId).toBe(selected?.id);
  if (selected) expect(frozen.prototypeDemographics).toEqual(selected.prototypeDemographics);
  expect(frozen.presentation).toContain(name);
  expect(frozen.presentation).not.toMatch(/\{patient(?:Name|Age|Sex)\}/);
  if (selected) frozenProfiles.add(selected.id);
  return next;
}

function tick(state: GameState, id: string): GameState {
  return gameReducer(state, { type: "ADVANCE_TICK", operationId: id, advancedAtRealMs: REAL_MS });
}

function ready(state: GameState, encounterId: string, prefix: string): GameState {
  let next = state;
  for (let count = 0; count < 1_500; count++) {
    if (getCurrentQuestion(next, encounterId)) return next;
    const encounter = next.encounters[encounterId];
    if (!encounter) throw new Error(`${encounterId} disappeared before its task`);
    next = encounter.lifecycle === "waiting_unopened" && encounter.patientMovement === null
      ? gameReducer(next, { type: "OPEN_CHART", operationId: `${prefix}.open.${count}`, encounterId })
      : tick(next, `${prefix}.tick.${count}`);
  }
  throw new Error(`${encounterId} never became answer-ready`);
}

function submit(state: GameState, encounterId: string, choiceId: string, id: string, reviewedAtMs = REAL_MS): GameState {
  const question = getCurrentQuestion(state, encounterId)!;
  const command = { type: "SUBMIT_ANSWER" as const, operationId: id, encounterId, decisionNodeId: question.node.id, answerChoiceId: choiceId, reviewedAtMs };
  const next = gameReducer(state, command);
  expect(next.operationReceipts[id]?.status).toBe("applied");
  expect(gameReducer(next, command)).toBe(next);
  return next;
}

function roundTrip(state: GameState, encounterId: string): GameState {
  const encounter = clone(state.encounters[encounterId]);
  const histories = clone(state.learningHistories);
  let next: GameState;
  try {
    next = deserializeGameState(serializeGameState(state));
  } catch (error) {
    const evidenceDirectory = process.env.GS028_LEVEL3_EVIDENCE_DIR;
    if (evidenceDirectory) writeFileSync(resolve(evidenceDirectory, `save-plan-failure-${encounterId.replace(/[^a-z0-9.-]/gi, "_")}.json`), `${JSON.stringify({
      syntheticFixtureOnly: true, encounterId, caseId: encounter?.frozenCase.id, facilityTick: state.facilityTick,
      lifecycle: encounter?.lifecycle, step: encounter?.steps[encounter.currentNodeIndex],
      plan: encounter?.pendingResult?.diagnosticTiming ?? encounter?.terminalTestOrder?.diagnosticTiming,
      relatedOperations: state.serviceOperations.filter((item) => item.actorId === encounterId),
      resources: state.rooms.filter((item) => ["room.ct", "room.reading", "room.training"].includes(item.roomDefinitionId)),
      employees: state.employees.map((item) => ({ id: item.id, role: item.staffRoleDefinitionId, location: item.location, training: item.training })),
      error: error instanceof Error ? error.message : String(error),
    }, null, 2)}\n`);
    throw error;
  }
  // DEFECT-M9-1: preserve overdue idle timers. An open chart resets only its
  // attention timestamps under the existing central loader rules.
  // No clinical/satisfaction value, frozen order identity, route, phase,
  // ready time, narrative or learning history is ignored.
  if (encounter && state.openChartEncounterId === encounterId) {
    encounter.idleWaitingSinceTick = null;
    encounter.lastSatisfactionDecayAtTick = state.facilityTick;
    encounter.feedAttentionKind = null;
    encounter.feedAttentionStartedAtTick = null;
  }
  expect(clone(next.encounters[encounterId])).toEqual(encounter);
  expect(next.learningHistories).toEqual(histories);
  return next;
}

function acknowledge(state: GameState, encounterId: string, id: string): GameState {
  const encounter = state.encounters[encounterId]!;
  const command = { type: "ACKNOWLEDGE_DECISION_FEEDBACK" as const, operationId: id, encounterId, decisionNodeId: encounter.steps[encounter.currentNodeIndex]!.decisionNodeId };
  const next = gameReducer(state, command);
  expect(next.operationReceipts[id]?.status).toBe("applied");
  expect(gameReducer(next, command)).toBe(next);
  return next;
}

function closeAndDepart(state: GameState, encounterId: string, prefix: string): GameState {
  const command = { type: "ACKNOWLEDGE_TERMINAL_FEEDBACK" as const, operationId: `${prefix}.terminal`, encounterId };
  let next = gameReducer(state, command);
  expect(next.operationReceipts[command.operationId]?.status).toBe("applied");
  expect(gameReducer(next, command)).toBe(next);
  const close = { type: "CLOSE_CHART" as const, operationId: `${prefix}.close`, encounterId };
  next = gameReducer(next, close);
  expect(next.operationReceipts[close.operationId]?.status).toBe("applied");
  expect(gameReducer(next, close)).toBe(next);
  expect(next.encounters[encounterId]?.lifecycle).toBe("resolved");
  for (let count = 0; count < 1_500; count++) {
    const encounter = next.encounters[encounterId];
    if (encounter?.patientLocation === null && encounter.patientMovement === null) return next;
    next = tick(next, `${prefix}.depart.${count}`);
  }
  throw new Error(`${encounterId} did not depart`);
}

function assertPreviews(state: GameState, encounterId: string, mode: string): void {
  const question = getCurrentQuestion(state, encounterId)!;
  const entry = timings.find((item) => item.nodeId === question.node.id)!;
  for (const choice of question.node.answerChoices) {
    const timing = entry.classification.kind === "test_choices" ? entry.classification.choices.find((item) => item.choiceId === choice.id)!.timing : { kind: "no_test" } as const;
    const before = JSON.stringify(state);
    const preview = getAnswerChoiceServicePreview(state, encounterId, choice.id);
    expect(JSON.stringify(state)).toBe(before);
    if (timing.kind === "no_test") {
      if (entry.classification.kind === "no_test") expect(preview, `${question.node.id}/${choice.id}`).toBeNull();
      else expect(preview).toEqual({ kind: "no_test", answerChoiceId: choice.id, durationTicks: null,
        serviceId: null, serviceDisplayName: null, routeId: null, routeDisplayName: null, timingProfileId: null });
      continue;
    }
    const record = exact.find((item) => item.nodeId === question.node.id && item.choiceId === choice.id)!;
    expect(preview).toMatchObject({ kind: "test", timingProfileId: timing.timingProfileId });
    const plan = preview!.diagnosticTiming!;
    expect(plan).toBeDefined();
    expect(plan.execution).toBe(record.disposition.kind === "not_executed" ? "preview_only" : "supported");
    if (preview!.durationTicks !== null) {
      expect(preview!.durationTicks).toBeGreaterThan(0);
      expect(preview!.durationTicks).toBe(Math.max(...plan.phases.map((phase) => phase.forecast.endsAtTick)) - state.facilityTick);
    }
    choicePreviewEvidence.set(`${question.node.id}|${choice.id}|${mode}`, { caseId: entry.caseId, nodeId: question.node.id,
      questionVariantId: question.node.questionVariantId, choiceId: choice.id, choiceLabel: choice.label, mode, preview });
  }
}

function noExtraService(state: GameState, encounterId: string): void {
  expect(state.serviceOperations.filter((item) => item.actorId === encounterId)).toEqual([]);
  expect(state.serviceIncomeReceipts.filter((item) => item.actorId === encounterId)).toEqual([]);
  expect(state.encounters[encounterId]?.terminalTestOrder).toBeUndefined();
}

function markReviewed(state: GameState, id: string, dueAtMs: number): void {
  const template = Object.values(state.learningHistories)[0]!;
  state.learningHistories[id] = { conceptId: id, card: { ...template.card, dueAtMs, lastReviewAtMs: REAL_MS - 10_000, reps: 1 }, reviews: [{} as ConceptReviewEvidence] };
}
function standalone(id: string): SyntheticClinicalCase {
  const clinicalCase = cases.find((item) => item.decisionNodes.length === 1 && item.decisionNodes[0]!.primaryConceptId === id);
  if (!clinicalCase) throw new Error(`${id} lacks an independent sibling`);
  return clinicalCase;
}
function ordinaryPool(state: GameState): SyntheticClinicalCase[] {
  const capabilities = getCurrentCapabilities(state);
  return PROTOTYPE_DOMAIN_CONTEXT.clinicalRelease.cases.filter((item) => item.participant?.kind !== "employee_discussion" && item.routineEligible && item.earliestFacilityStage <= state.facilityLevel && item.requiredCapabilityIds.every((id) => capabilities.has(id)));
}
function complete(c:SyntheticClinicalCase,path:"correct"|0|1|2,index:number){
 const id=`encounter.gs028g.${index}.${path}`;
 let state=ready(admit(prepared(id),c,id),id,id);state=roundTrip(state,id);
 for(let i=0;i<c.decisionNodes.length;i++){
  state=ready(state,id,`${id}.${i}.ready`);const node=c.decisionNodes[i]!;
  expect(getCurrentQuestion(state,id)?.node.id).toBe(node.id);assertPreviews(state,id,"level3");
  const wrong=node.answerChoices.filter(a=>!a.isCorrect);
  const key=path==="correct"?node.answerChoices.find(a=>a.isCorrect)!:wrong[path%wrong.length]!;
  const xp=state.clinicalXp;state=submit(state,id,key.id,`${id}.${i}.submit`,REAL_MS+index*100+i);
  expect(state.clinicalXp-xp).toBe(path==="correct"?PROTOTYPE_DOMAIN_CONTEXT.balanceRelease.clinicalSettlement.clinicalXpPerCorrectFirstAnswer:PROTOTYPE_DOMAIN_CONTEXT.balanceRelease.clinicalSettlement.clinicalXpPerIncorrectFirstAnswer);
  expect(state.learningHistories[node.primaryConceptId]?.reviews).toEqual([expect.objectContaining({answerChoiceId:key.id,correct:path==="correct",rating:path==="correct"?"Good":"Again"})]);
  expect(state.learningHistories[node.primaryConceptId]?.card.reps).toBe(1);
  expect(state.encounters[id]?.steps[i]?.answer).toMatchObject({answerChoiceId:key.id,correctedForward:path!=="correct"&&i<c.decisionNodes.length-1});
  const seen=coverage.get(node.id)??new Set<string>();seen.add(key.id);coverage.set(node.id,seen);
  noExtraService(state,id);expect(state.encounters[id]?.pendingResult).toBeNull();state=roundTrip(state,id);
  if(i<c.decisionNodes.length-1){
   expect(state.learningHistories[c.decisionNodes[i+1]!.primaryConceptId]?.reviews).toEqual([]);
   expect(getCurrentQuestion(state,id)).toBeNull();
   state=acknowledge(state,id,`${id}.${i}.ack`);state=roundTrip(state,id);
   state=ready(state,id,`${id}.${i}.next`);
   expect(getCurrentQuestion(state,id)?.node.currentUpdate).toBe(c.decisionNodes[i+1]!.currentUpdate?.replaceAll("{patientName}",state.encounters[id]!.patientDisplayName));
   expect(state.encounters[id]?.deliveredResultNarratives).toEqual([]);
  }
 }
 expect(state.encounters[id]?.lifecycle).toBe("resolved_summary_available");
 state=closeAndDepart(roundTrip(state,id),id,id);
 for(const n of c.decisionNodes)expect(state.learningHistories[n.primaryConceptId]?.reviews).toHaveLength(1);
 roundTrip(state,id);
}
